      {
        "ballot_id": "B034",
        "laureates": [
          "Hidetoshi Katori",
          "Jun Ye"
        ],
        "citation": "For the invention and realization of optical lattice clocks."
      }
    ]
  },
  "alternatives": [
    "B037",
    "B026"
  ],
  "statement": {
    "case_for": "Optical lattice clocks combine control of atomic motion with exceptionally precise optical frequency measurement. Their reproducible performance across laboratories has made them important instruments for tests of fundamental physics and precision measurement. Katori and Ye provide a focused attribution for complementary advances in the concept and its experimental realization.",
    "case_against": "The field has a broad international history, and the boundary between the original lattice-clock invention and later performance advances is not self-evident. The clocks continue to improve, so some of their eventual scientific reach remains ahead of us.",
    "responses": [
      {
        "member_id": "danielsson-ulf",
        "point": "He notes that many clock pioneers contributed and that the prize boundary needs definition.",
        "response": "That is a real attribution issue. I would define the contribution narrowly as the optical lattice clock concept and its experimental realization, represented here by Katori and Ye, rather than trying to recognize every later advance in clock performance."
      },
      {
        "member_id": "olsson-eva",
        "point": "She emphasizes that the original invention and subsequent advances need careful distinction, while observing that clocks have been repeatedly realized and improved.",
        "response": "The continuing development does not erase the mature experimental basis: the method is independently realized and already enables precise comparisons. I agree the citation should stay with the invention and realization, and not imply that all later applications or improvements belong to this pair."
      }
    ],
    "uncertainties": [
      "The historical boundary between the core lattice-clock invention and later generations of clock technology needs careful review."
    ],
    "conflict_note": "None apparent from the supplied profile."
  }
}
